export const hasExactCurrentController = (
  responsibilities: readonly Responsibility[],
  context: Pick<OrganizationIcoApplicabilityContext, 'authority' | 'processingScopeRef'>,
  decision: typeof PrivacyApplicabilityDecisionSchema.Type,
  evaluatedAt: string,
): boolean =>
  responsibilities.filter(
    (assignment) =>
      assignment.role === 'CONTROLLER' &&
      assignment.scopeRef.scopeId === context.processingScopeRef.scopeId &&
      assignment.scopeRef.scopeType === context.processingScopeRef.scopeType &&
      isPrivacyInstantAtOrBefore(assignment.effectiveFrom, evaluatedAt) &&
      (Option.isNone(assignment.effectiveTo) || isPrivacyInstantAfter(assignment.effectiveTo.value, evaluatedAt)) &&
      sameOwner(assignment.holder.holder, context.authority.controllerRef) &&
      decision.responsibilityAssignmentRefs.some((ref) => sameOwner(ref, assignment.assignmentRef)),
  ).length === 1;

const organizationClassificationIsCurrent = (
  request: OrganizationIcoApplicabilityRequest,
  decision: typeof PrivacyApplicabilityDecisionSchema.Type,
  business: TrustedPrivacyApplicabilityBusinessFactAuthorityResult,
  policies: readonly PrivacyApplicabilityPolicy[],
  evaluatedAt: string,
): boolean => {
  const reevaluated = resolvePrivacyApplicability({
    authority: business.authority,
    authorityEvidenceRefs: business.evidenceRefs,
    authorityReceiptRef: business.receiptRef,
    evaluatedAt,
    policies,
    proposedActivity: decision.proposedActivity,
    responsibilityAssignmentRefs: decision.responsibilityAssignmentRefs,
    scope: business.scope,
  });
  const marker = reevaluated.nonPersonalApplicability;
  return !(
    marker === undefined ||
    marker.kind !== 'ORGANIZATION_ICO_ONLY' ||
    marker.holdBehavior !== 'NO_ACTIVE_SCOPE_HOLD' ||
    marker.fieldContractVersion !== OrganizationIcoFieldContractVersion ||
    !request.fields.every((field) => new Set(marker.allowedFields).has(field)) ||
    !privacyApplicabilityDecisionsAreEquivalent({ ...reevaluated, evaluatedAt: decision.evaluatedAt }, decision)
  );
};

export const evaluateOrganizationIcoApplicability = Effect.fn('Privacy.evaluateOrganizationIcoApplicability')(
  function* evaluate(
    request: OrganizationIcoApplicabilityRequest,
    scope: OperationalScope,
    services: OrganizationIcoApplicabilityServices,
    evaluatedAt: string,
  ): Effect.fn.Return<OrganizationIcoApplicabilityResponse, ReadHandlerUnavailable> {
    const deny = (
      reason: string,
      outcome: 'DENIED' | 'INDETERMINATE' = 'DENIED',
    ): OrganizationIcoApplicabilityResponse => ({ evaluatedAt, outcome, reason });
    const contexts = services.contexts.filter(
      (context) =>
        requestEquivalent(context.request, request) && organizationIcoContextMatches(context, scope, evaluatedAt),
    );
    const [context] = contexts;
    if (contexts.length !== 1 || context === undefined || scope.legalEntityId === undefined) {
      return deny('CURRENT_CONTEXT_REQUIRED');
    }
    const proof = yield* services.proof(request);
    if (proof.outcome !== 'CURRENT_ORGANIZATION' || !currentProofMatches(proof, request, evaluatedAt)) {
      return deny('CURRENT_ORGANIZATION_REQUIRED');
    }
    const business = organizationIcoBusinessFacts(context, proof, evaluatedAt);
    const [stored, history, policies, purpose, responsibilities, hold] = yield* Effect.all(
      [
        services.decision(context.decisionRef),
        services.repository.listApplicabilityDecisions(scope.tenantId, scope.legalEntityId),
        services.repository.listApplicabilityPolicies(scope.tenantId, scope.legalEntityId),
        services.purposes.get(scope.tenantId, scope.legalEntityId, context.authority.purposeRef.resourceId),
        services.repository.listResponsibilities(scope.tenantId, scope.legalEntityId),
        services.holds(`${OrganizationIcoFieldContractVersion}:${request.partyRef.resourceId}`, evaluatedAt),
      ],
      { concurrency: 4 },
    ).pipe(Effect.mapError(unavailable));
    if (hold !== 'CLEAR') {
      return deny('CURRENT_SCOPE_HOLD', hold === 'INDETERMINATE' ? 'INDETERMINATE' : 'DENIED');
    }
    if (Option.isNone(stored) || Option.isNone(purpose)) {
      return deny('NATIVE_DECISION_AND_PURPOSE_REQUIRED');
    }
    const decision = stored.value;
    const versions = purpose.value.versions.filter(
      (version) =>
        isPrivacyInstantAtOrBefore(version.effectiveFrom, evaluatedAt) &&
        (version.effectiveTo === null || isPrivacyInstantAfter(version.effectiveTo, evaluatedAt)),
    );
    if (
      purpose.value.lifecycle !== 'ACTIVE' ||
      !sameOwner(purpose.value.purposeRef, context.authority.purposeRef) ||
      versions.length !== 1 ||
      versions.at(0)?.versionId !== context.authority.purposeVersionRef.resourceId
    ) {
      return deny('CURRENT_PURPOSE_REQUIRED');
    }
    if (!hasExactCurrentController(responsibilities, context, decision, evaluatedAt)) {
      return deny('CURRENT_CONTROLLER_REQUIRED');
    }
    const latest = latestPrivacyApplicabilityDecisionsForExactAuthorities(history, business.scope, evaluatedAt).filter(
      (candidate) => candidate.authority !== undefined && authorityEquivalent(candidate.authority, context.authority),
    );
    if (
      latest.length !== 1 ||
      !latest.some((candidate) => privacyApplicabilityDecisionsAreEquivalent(candidate, decision))
    ) {
      return deny('NATIVE_DECISION_SUPERSEDED');
    }
    if (!organizationClassificationIsCurrent(request, decision, business, policies, evaluatedAt)) {
      return deny('EXPLICIT_CURRENT_ICO_CLASSIFICATION_REQUIRED');
    }
    return {
      allowedFields: request.fields,
      applicabilityDecisionRef: context.decisionRef,
      authorityIncarnation: context.authorityIncarnation,
      authorityRevision: context.authorityRevision,
      evaluatedAt,
      evidenceRefs: business.evidenceRefs,
      fieldContractVersion: OrganizationIcoFieldContractVersion,
      outcome: 'NOT_APPLICABLE',
      partyRef: request.partyRef,
      partyRevision: proof.partyRevision,
      policyRevisions: decision.policyIdentities.map((identity) => ({
        policyRef: identity.policyKey,
        revision: identity.policyVersion,
      })),
    };
  },
);

type Transaction = Parameters<ReadServiceFactory<Readonly<Record<string, never>>>>[0];
export const organizationIcoNativeEvidenceForScope = Effect.fn('Privacy.organizationIcoNativeEvidenceForScope')(
  function* nativeEvidence(
    transaction: Transaction,
    scope: OperationalScope,
  ): Effect.fn.Return<
    Pick<OrganizationIcoApplicabilityServices, 'decision' | 'holds' | 'purposes' | 'repository'>,
    OperationContextUnavailable,
    Crypto.Crypto
  > {
    const { purposes, repository } = yield* Effect.all(
      {
        purposes: processingPurposeRepositoryForScope(transaction, scope),
        repository: privacyOperationRepositoryForScope(transaction, scope),
      },
      { concurrency: 2 },
    );
    return {
      decision: (decisionRef: string) =>
        transaction
          .select({ record: applicabilityDecisions.decisionRecord })
          .from(applicabilityDecisions)
          .where(
            and(
              eq(applicabilityDecisions.tenantId, scope.tenantId),
              eq(applicabilityDecisions.legalEntityId, scope.legalEntityId ?? ''),
              eq(applicabilityDecisions.decisionId, decisionRef),
            ),
          )
          .limit(1)
          .pipe(
            Effect.mapError(unavailable),
            Effect.flatMap((rows) =>
              rows.at(0) === undefined
                ? Effect.succeed(Option.none())
                : Schema.decodeUnknownEffect(PrivacyApplicabilityDecisionSchema)(rows[0]?.record).pipe(
                    Effect.map(Option.some),
                    Effect.mapError(unavailable),
                  ),
            ),
          ),
      holds: Effect.fn('Privacy.organizationIcoCurrentHolds')(function* currentHolds(
        contentScopeRef: string,
        asOf: string,
      ) {
        const rows = yield* transaction
          .select({ record: legalHolds.holdRecord, recordedAt: legalHolds.recordedAt, ref: legalHolds.holdRef })
          .from(legalHolds)
          .where(and(eq(legalHolds.tenantId, scope.tenantId), eq(legalHolds.legalEntityId, scope.legalEntityId ?? '')))
          .pipe(Effect.mapError(unavailable));
        const latest = new Map<string, { instant: DateTime.Utc; record: unknown }>();
        for (const row of rows) {
          const instant = DateTime.makeUnsafe(row.recordedAt);
          if (DateTime.toEpochMillis(instant) > DateTime.toEpochMillis(DateTime.makeUnsafe(asOf))) {
            continue;
          }
          const prior = latest.get(row.ref);
          if (prior !== undefined && DateTime.toEpochMillis(prior.instant) === DateTime.toEpochMillis(instant)) {
            return 'INDETERMINATE' as const;
          }
          if (prior === undefined || DateTime.toEpochMillis(instant) > DateTime.toEpochMillis(prior.instant)) {
            latest.set(row.ref, { instant, record: row.record });
          }
        }
        const states = yield* Effect.forEach(
          [...latest.values()],
          Effect.fn('Privacy.organizationIcoAssessCurrentHold')(function* assessCurrentHold(row) {
            const hold = yield* Schema.decodeUnknownEffect(PrivacyLegalHoldSchema)(row.record).pipe(
              Effect.mapError(unavailable),
            );
            if (!validateRetentionProtection(hold).valid) {
              return 'INDETERMINATE' as const;
            }
            if (hold.contentScopeRefs.includes(contentScopeRef) && isTimedRetentionProtectionActive(hold, asOf)) {
              return isPrivacyInstantAfter(hold.reviewDueAt, asOf) ? ('BLOCKED' as const) : ('INDETERMINATE' as const);
            }
            return 'CLEAR' as const;
          }),
          { concurrency: 1 },
        );
        if (states.includes('INDETERMINATE')) {
          return 'INDETERMINATE' as const;
        }
        if (states.includes('BLOCKED')) {
          return 'BLOCKED' as const;
        }

        return 'CLEAR' as const;
      }),
      purposes,
      repository,
    };
  },
);

